function maximumTotalCost(nums) {
  const n = nums.length;
  const cost = (l, r) => {
    let total = 0;
    for (let j = l; j <= r; j++) total += (j - l) % 2 === 0 ? nums[j] : -nums[j];
    return total;
  };
  const best = new Array(n + 1).fill(-Infinity);
  best[0] = 0;
  for (let end = 1; end <= n; end++)
    for (let start = 0; start < end; start++)
      best[end] = Math.max(best[end], best[start] + cost(start, end - 1));
  return best[n];
}

