function generate(rand, size) {
  if (size === 'large') {
    const n = 2000;
    return [Array.from({ length: n }, () => Math.floor(rand() * 2000000001) - 1000000000)];
  }
  const n = 1 + Math.floor(rand() * 9);
  const mode = rand();
  const pick = () => {
    if (mode < 0.15) return rand() < 0.5 ? 1000000000 : -1000000000;
    if (mode < 0.3) return -1 - Math.floor(rand() * 6);
    return Math.floor(rand() * 11) - 5;
  };
  return [Array.from({ length: n }, pick)];
}
